261	     * create-owner duplicate/identity checks ignore owners flagged deleted.
262	     */
263	    public boolean isDeleted() {
264	        return this.deleted;
265	    }
266	
267	    public void setDeleted(boolean deleted) {
268	        this.deleted = deleted;
269	    }
270	
271	    /**
272	     * The owner's membership points, accumulated from four factors: start at 0, add 2
273	     * when an email is present, add 1 when {@code namesakeCount} is 0, add 2 for a
274	     * household of 3 or more members, and add 3 when the owner's tenure exceeds 365
275	     * days. The tenure points are the only route to 6 or more: because a newly created
276	     * owner has zero tenure, a new owner scores at most 5 points (2 email + 1 namesake
277	     * + 2 household).
278	     */
279	    @Transient
280	    public int getMembershipPoints() {
281	        int points = 0;
282	        if (this.email != null && !this.email.isBlank()) {
283	            points += 2;
284	        }
285	        if (this.namesakeCount != null && this.namesakeCount == 0) {
286	            points += 1;
287	        }
288	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
289	            points += 2;
290	        }
291	        if (getTenureDays() > 365) {
292	            points += 3;
293	        }
294	        return points;
295	    }
296	
297	    /**
298	     * The owner's numeric membership level, derived from {@link #getMembershipPoints()}:
299	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly
300	     * created owner scores at most 5 points (tenure being the only route to 6), a new
301	     * owner never exceeds level 3.
302	     */
303	    @Transient
304	    public int getMembershipLevel() {
305	        int points = getMembershipPoints();
306	        if (points <= 1) {
307	            return 1;
308	        }
309	        if (points <= 3) {
310	            return 2;
311	        }
312	        if (points <= 5) {
313	            return 3;
314	        }
315	        return 4;
316	    }
317	
318	    /**
319	     * The owner's tenure in whole days: the span from {@code registrationDate} to today.
320	     * Zero when no registration date is set, and zero for an owner registered today, so
321	     * the tenure point of {@link #getMembershipLevel()} is never earned at creation.
322	     */
323	    @Transient
324	    public long getTenureDays() {
325	        if (this.registrationDate == null) {
326	            return 0;
327	        }
328	        return java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
329	    }
330	
331	    /**
332	     * The owner's canonical region, preferring the postcode over the city.
333	     *
334	     * <p>The 4-digit postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
335	     * QLD 4000-4099); only when the postcode is absent or in no known range does this
336	     * fall back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
337	     * Brisbane-&gt;QLD). Anything unresolved is {@code "UNKNOWN"}. This single derivation
